(async()=>{
const $=id=>document.getElementById(id), fmt=new Intl.NumberFormat('en-AU',{maximumFractionDigits:1}),NS='http://www.w3.org/2000/svg';
const svgEl=(tag,attrs={},txt)=>{const n=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);if(txt!==undefined)n.textContent=txt;return n};
let map,markers,markerList=[],data,latest;
const colors=['#345eea','#67917c','#c38651'];
function activate(view){for(const kind of ['flow','map']){const active=kind===view;$(`${kind}-tab`).setAttribute('aria-selected',String(active));$(`${kind}-tab`).tabIndex=active?0:-1;$(`${kind}-panel`).hidden=!active}if(view==='map'){if(!map)initMap();map.invalidateSize();renderMap()}}
for(const kind of ['flow','map']){$(`${kind}-tab`).addEventListener('click',()=>activate(kind));$(`${kind}-tab`).addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?'flow':e.key==='End'?'map':kind==='flow'?'map':'flow';activate(next);$(`${next}-tab`).focus()}})}
function initMap(){if(!window.L){$('demo-map').textContent='Map library could not load. Please refresh.';return}map=L.map('demo-map',{scrollWheelZoom:false}).setView([-26,134],3);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>'}).addTo(map);markers=L.markerClusterGroup({maxClusterRadius:48,showCoverageOnHover:false,spiderfyOnMaxZoom:true,zoomToBoundsOnClick:true,iconCreateFunction:cluster=>L.divIcon({html:'<span>'+cluster.getChildCount()+'</span>',className:'facility-cluster',iconSize:[38,38]})}).addTo(map)}
function selected(){const d=data[$('demo-year').value],industry=$('demo-industry').value;return{d,industry,flows:d.flows.filter(x=>industry==='All'||x[0]===industry),facilities:d.facilities.filter(x=>industry==='All'||x.industry===industry)}}
function renderFlow(){const {flows}=selected(),totals={};for(const[i,s,v]of flows)totals[i]=(totals[i]||0)+v;const industries=Object.keys(totals).sort((a,b)=>totals[b]-totals[a]).slice(0,3);let links=flows.filter(x=>industries.includes(x[0]));const substances={};for(const[i,s,v]of links)substances[s]=(substances[s]||0)+v;const names=Object.keys(substances).sort((a,b)=>substances[b]-substances[a]).slice(0,6);links=links.filter(x=>names.includes(x[1]));const total=links.reduce((a,x)=>a+x[2],0);const svg=svgEl('svg',{viewBox:'0 0 850 430',role:'group','aria-label':`Industry to pollutant flows for ${$('demo-year').value}`});if(!total){svg.append(svgEl('text',{x:30,y:50},'No positive recorded flows for this selection.'));$('demo-flow').replaceChildren(svg);return}
const leftTotals={},rightTotals={};for(const[i,s,v]of links){leftTotals[i]=(leftTotals[i]||0)+v;rightTotals[s]=(rightTotals[s]||0)+v}const gap=17,scale=(310-gap*(names.length-1))/total;let pos=40;const left={},right={};for(const i of industries){left[i]={y:pos,offset:0,h:(leftTotals[i]||0)*scale};pos+=left[i].h+gap}pos=40;for(const s of names){right[s]={y:pos,offset:0,h:rightTotals[s]*scale};pos+=right[s].h+gap}
for(const[i,s,v]of links){const a=left[i],b=right[s],h=v*scale,ay=a.y+a.offset,by=b.y+b.offset;a.offset+=h;b.offset+=h;const path=svgEl('path',{d:`M210 ${ay} C390 ${ay} 460 ${by} 640 ${by} L640 ${by+h} C460 ${by+h} 390 ${ay+h} 210 ${ay+h} Z`,fill:colors[industries.indexOf(i)],opacity:.45,class:'flow-link',tabindex:0,role:'button','aria-label':`${i} to ${s}: ${fmt.format(v)} kilograms`});const message=`${i} → ${s}: ${fmt.format(v)} kg · ${$('demo-year').value}`;path.append(svgEl('title',{},message));const inspect=()=>{$('flow-detail').textContent=message;svg.querySelectorAll('.flow-link').forEach(n=>n.setAttribute('opacity',n===path?.9:.15))};path.addEventListener('mouseenter',inspect);path.addEventListener('focus',inspect);path.addEventListener('click',inspect);path.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();inspect()}});svg.append(path)}
for(const i of industries){const n=left[i];svg.append(svgEl('rect',{x:198,y:n.y,width:12,height:Math.max(n.h,1),fill:colors[industries.indexOf(i)],rx:2}));const words=i.split(' ');const t=svgEl('text',{x:185,y:n.y+Math.max(n.h/2,8),'text-anchor':'end'});t.append(svgEl('tspan',{x:185,dy:0},words.slice(0,3).join(' ')));if(words.length>3)t.append(svgEl('tspan',{x:185,dy:15},words.slice(3).join(' ')));svg.append(t)}
for(const s of names){const n=right[s];svg.append(svgEl('rect',{x:640,y:n.y,width:12,height:Math.max(n.h,1),fill:'#8b9c92',rx:2}));const label=s.length>28?s.slice(0,26)+'…':s,t=svgEl('text',{x:663,y:n.y+Math.max(n.h/2,8)},label);t.append(svgEl('title',{},s));svg.append(t)}svg.append(svgEl('text',{x:198,y:400},'INDUSTRIES'),svgEl('text',{x:640,y:400},'SUBSTANCES'));$('demo-flow').replaceChildren(svg);$('flow-detail').textContent='Hover, tap, or use Tab and Enter to inspect a flow.'}
function renderMap(){if(!map)return;const{facilities}=selected();markers.clearLayers();markerList=[];const max=Math.max(...facilities.map(f=>f.kg),1);$('demo-facility').replaceChildren();const opt=document.createElement('option');opt.value='';opt.textContent='Select a facility…';$('demo-facility').append(opt);facilities.sort((a,b)=>b.kg-a.kg).forEach((f,index)=>{const content=document.createElement('div');const strong=document.createElement('strong');strong.textContent=f.name;content.append(strong);for(const t of [f.industry,`${fmt.format(f.kg)} kg · ${f.substances} recorded substances`]){const div=document.createElement('div');div.textContent=t;content.append(div)}const m=L.circleMarker([f.lat,f.lng],{radius:3+Math.sqrt(f.kg/max)*6,color:'#ffffff',weight:1,fillColor:'#345eea',fillOpacity:.72}).bindPopup(content).bindTooltip(f.name).addTo(markers);markerList.push(m);const o=document.createElement('option');o.value=index;o.textContent=`${f.name} · ${fmt.format(f.kg)} kg`;$('demo-facility').append(o)});$('map-detail').textContent=`${facilities.length} facility markers shown · ${$('demo-year').value}. Cluster numbers count displayed facilities. Click a cluster to zoom, or choose a facility below.`}
function render(){const{flows,facilities}=selected();$('demo-total').textContent=`${fmt.format(flows.reduce((a,x)=>a+x[2],0))} kg`;$('demo-facilities').textContent=facilities.length;renderFlow();if(map)renderMap()}
try{const r=await fetch('assets/shiny/explorer.json');if(!r.ok)throw Error('Data could not load');data=await r.json();const years=Object.keys(data);latest=years.at(-1);for(const year of years){const o=document.createElement('option');o.value=year;o.textContent=year;$('demo-year').append(o)}$('demo-year').value=latest;const inds=[...new Set(Object.values(data).flatMap(d=>d.flows.map(x=>x[0])))].sort();for(const name of ['All',...inds]){const o=document.createElement('option');o.value=name;o.textContent=name==='All'?'All industries':name;$('demo-industry').append(o)}$('demo-year').disabled=false;$('demo-industry').disabled=false;for(const id of ['demo-year','demo-industry'])$(id).addEventListener('change',render);$('demo-reset').addEventListener('click',()=>{$('demo-year').value=latest;$('demo-industry').value='All';render();if(map)map.setView([-26,134],3)});$('demo-facility').addEventListener('change',()=>{const index=$('demo-facility').value;if(index!==''){const m=markerList[Number(index)];markers.zoomToShowLayer(m,()=>{map.setView(m.getLatLng(),Math.max(map.getZoom(),9));m.openPopup()})}});render()}catch(e){$('flow-detail').textContent='Project data could not load. Please refresh the page.';$('flow-detail').classList.add('explorer-error')}
})();
